import {
  GleapFrameManager,
  GleapConfigManager,
  GleapNotificationManager,
  GleapTranslationManager,
  GleapAiChatbarManager,
  GleapSession,
} from './Gleap';
import { loadIcon } from './UI';

export default class GleapFeedbackButtonManager {
  feedbackButton = null;
  injectedFeedbackButton = false;
  buttonHidden = null;
  lastButtonIcon = null;
  showingRedDot = false;
  removePressListeners = null;

  // Feedback button types
  static FEEDBACK_BUTTON_BOTTOM_RIGHT = 'BOTTOM_RIGHT';
  static FEEDBACK_BUTTON_BOTTOM_LEFT = 'BOTTOM_LEFT';
  static FEEDBACK_BUTTON_CLASSIC = 'BUTTON_CLASSIC';
  static FEEDBACK_BUTTON_CLASSIC_LEFT = 'BUTTON_CLASSIC_LEFT';
  static FEEDBACK_BUTTON_CLASSIC_BOTTOM = 'BUTTON_CLASSIC_BOTTOM';
  static FEEDBACK_BUTTON_NONE = 'BUTTON_NONE';

  // GleapFeedbackButtonManager singleton
  static instance;
  static getInstance() {
    if (!this.instance) {
      this.instance = new GleapFeedbackButtonManager();
    }
    return this.instance;
  }

  destroy() {
    if (this.removePressListeners) {
      this.removePressListeners();
      this.removePressListeners = null;
    }

    if (this.feedbackButton) {
      this.feedbackButton.remove();
      this.feedbackButton = null;
    }

    this.buttonHidden = null;
    this.lastButtonIcon = null;
    this.injectedFeedbackButton = false;
    this.instance = null;
  }

  /**
   * Toggles the feedback button visibility.
   * @param {*} show
   * @returns
   */
  toggleFeedbackButton(show) {
    this.buttonHidden = !show;

    GleapFeedbackButtonManager.getInstance().updateFeedbackButtonState();
    GleapNotificationManager.getInstance().updateContainerStyle();
  }

  updateRedDot(show) {
    var frameManager = GleapFrameManager.getInstance();
    if (!this.feedbackButton || this.buttonHidden || frameManager.isOpened()) {
      return;
    }

    const redDotClass = 'bb-feedback-button--red-dot';
    const existingDot = this.feedbackButton.querySelector(`.${redDotClass}`);

    if (show) {
      if (!existingDot) {
        const dot = document.createElement('div');
        dot.className = redDotClass;
        this.feedbackButton.appendChild(dot);
      }
    } else {
      if (existingDot) {
        existingDot.remove();
      }
    }
  }

  feedbackButtonPressed(fromKeyboard = false) {
    var frameManager = GleapFrameManager.getInstance();
    if (frameManager.isOpened()) {
      frameManager.hideWidget();
      this.updateRedDot(this.showingRedDot);
    } else {
      frameManager.setAppMode('widget');
      frameManager.showWidget();
      this.updateRedDot(false);
      // Opened from the keyboard: the keyboard moves into the messenger with it.
      if (fromKeyboard) {
        frameManager.focusFrame();
      }
    }
  }

  /**
   * The messenger closed while the keyboard was in it (Escape, its close button): the keyboard
   * comes back to the launcher instead of the top of the page.
   */
  restoreFocus() {
    if (!this.feedbackButton || !this.feedbackButton.isConnected) {
      return;
    }
    try {
      this.feedbackButton.focus({ preventScroll: true });
    } catch (e) {}
  }

  /**
   * Injects the feedback button into the current DOM.
   */
  injectFeedbackButton() {
    if (this.injectedFeedbackButton) {
      return;
    }
    this.injectedFeedbackButton = true;

    // A div (a <button> would take the host page's button styles), made a real button for the
    // keyboard and screen readers: Tab reaches it, Enter and Space open it.
    var elem = document.createElement('div');
    elem.setAttribute('role', 'button');
    elem.setAttribute('tabindex', '0');
    elem.addEventListener('click', () => {
      this.feedbackButtonPressed();
    });
    elem.addEventListener('keydown', (event) => {
      if (event.key === 'Enter' || event.key === ' ' || event.key === 'Spacebar') {
        event.preventDefault();
        this.feedbackButtonPressed(true);
      }
    });
    this.attachPressAnimation(elem);
    document.body.appendChild(elem);
    this.feedbackButton = elem;

    this.updateFeedbackButtonState();
  }

  /**
   * Scales the icon button down while held and springs it back on release.
   * The release listeners sit on the document so a press that ends outside
   * the button (drag off, cancelled touch) still springs back — it just
   * doesn't toggle the widget, since no click fires in that case.
   */
  attachPressAnimation(elem) {
    const pressedClass = 'bb-feedback-button--pressed';
    const springingClass = 'bb-feedback-button--springing';
    var springingTimeout = null;

    const press = () => {
      clearTimeout(springingTimeout);
      elem.classList.remove(springingClass);
      elem.classList.add(pressedClass);
    };

    const release = () => {
      if (!elem.classList.contains(pressedClass)) {
        return;
      }
      elem.classList.remove(pressedClass);
      elem.classList.add(springingClass);
      springingTimeout = setTimeout(() => {
        elem.classList.remove(springingClass);
      }, 550);
    };

    if (window.PointerEvent) {
      elem.addEventListener('pointerdown', press);
      document.addEventListener('pointerup', release);
      document.addEventListener('pointercancel', release);
      this.removePressListeners = () => {
        document.removeEventListener('pointerup', release);
        document.removeEventListener('pointercancel', release);
      };
    } else {
      elem.addEventListener('mousedown', press);
      elem.addEventListener('touchstart', press, { passive: true });
      document.addEventListener('mouseup', release);
      document.addEventListener('touchend', release);
      document.addEventListener('touchcancel', release);
      this.removePressListeners = () => {
        document.removeEventListener('mouseup', release);
        document.removeEventListener('touchend', release);
        document.removeEventListener('touchcancel', release);
      };
    }
  }

  updateNotificationBadge(count) {
    const notificationBadge = document.querySelector('.bb-notification-bubble');
    if (!notificationBadge) {
      return;
    }

    const notificationHiddenClass = 'bb-notification-bubble--hidden';
    if (count > 0 && !GleapFrameManager.getInstance().isOpened()) {
      notificationBadge.classList.remove(notificationHiddenClass);
      notificationBadge.innerText = count;
    } else {
      notificationBadge.classList.add(notificationHiddenClass);
    }
  }

  refresh() {
    const feedbackButton = document.querySelector('.bb-feedback-button');
    if (feedbackButton) {
      this.updateFeedbackButtonText();
      this.updateFeedbackButtonState();
    } else {
      this.injectedFeedbackButton = false;
      this.feedbackButton = null;
      this.buttonHidden = null;
      this.lastButtonIcon = null;
      this.injectFeedbackButton();
    }
  }

  updateFeedbackButtonText() {
    const flowConfig = GleapConfigManager.getInstance().getFlowConfig();

    if (
      !(
        flowConfig.feedbackButtonPosition === GleapFeedbackButtonManager.FEEDBACK_BUTTON_CLASSIC ||
        flowConfig.feedbackButtonPosition === GleapFeedbackButtonManager.FEEDBACK_BUTTON_CLASSIC_BOTTOM ||
        flowConfig.feedbackButtonPosition === GleapFeedbackButtonManager.FEEDBACK_BUTTON_CLASSIC_LEFT
      )
    ) {
      return;
    }

    const feedbackButton = document.querySelector('.bb-feedback-button-classic');
    if (!feedbackButton) {
      return;
    }

    feedbackButton.innerText = flowConfig.widgetButtonText;
  }

  /**
   * Updates the feedback button state
   * @returns
   */
  updateFeedbackButtonState() {
    GleapAiChatbarManager.getInstance().updateUIVisibility();

    if (this.feedbackButton === null) {
      return;
    }

    const flowConfig = GleapConfigManager.getInstance().getFlowConfig();

    var buttonIcon = '';
    if (flowConfig.buttonLogo) {
      buttonIcon = `<img class="bb-logo-logo" src="${flowConfig.buttonLogo}" alt="Feedback Button" />`;
    } else {
      buttonIcon = loadIcon('button', '#fff');
    }

    // Opening the widget re-runs this while the release spring is mid-flight;
    // the wholesale className reset must not swallow the press animation classes.
    const pressAnimationClasses = ['bb-feedback-button--pressed', 'bb-feedback-button--springing'].filter(
      (className) => this.feedbackButton.classList.contains(className)
    );
    this.feedbackButton.className = 'bb-feedback-button gleap-font rr-block';
    pressAnimationClasses.forEach((className) => this.feedbackButton.classList.add(className));
    this.feedbackButton.setAttribute('dir', GleapTranslationManager.getInstance().isRTLLayout ? 'rtl' : 'ltr');
    const isWidgetOpen = GleapFrameManager.getInstance().isOpened();
    this.feedbackButton.setAttribute('aria-expanded', isWidgetOpen ? 'true' : 'false');
    this.feedbackButton.setAttribute(
      'aria-label',
      (flowConfig.widgetButtonText && `${flowConfig.widgetButtonText}`.trim()) || 'Open support chat'
    );

    if (
      flowConfig.feedbackButtonPosition === GleapFeedbackButtonManager.FEEDBACK_BUTTON_CLASSIC ||
      flowConfig.feedbackButtonPosition === GleapFeedbackButtonManager.FEEDBACK_BUTTON_CLASSIC_BOTTOM ||
      flowConfig.feedbackButtonPosition === GleapFeedbackButtonManager.FEEDBACK_BUTTON_CLASSIC_LEFT
    ) {
      this.feedbackButton.classList.add('bb-feedback-button--classic-button-style');

      this.feedbackButton.innerHTML = `<div class="bb-feedback-button-classic ${
        flowConfig.feedbackButtonPosition === GleapFeedbackButtonManager.FEEDBACK_BUTTON_CLASSIC_LEFT
          ? 'bb-feedback-button-classic--left'
          : ''
      }${
        flowConfig.feedbackButtonPosition === GleapFeedbackButtonManager.FEEDBACK_BUTTON_CLASSIC_BOTTOM
          ? 'bb-feedback-button-classic--bottom'
          : ''
      }">${flowConfig.widgetButtonText}</div>`;
    } else {
      if (buttonIcon !== this.lastButtonIcon) {
        this.feedbackButton.innerHTML = `<div class="bb-feedback-button-icon">${buttonIcon}${loadIcon(
          'arrowdown',
          '#fff'
        )}</div><div class="bb-notification-bubble bb-notification-bubble--hidden"></div>`;
      }
    }

    // Prevent dom update if not needed.
    this.lastButtonIcon = buttonIcon;

    var hideButton = false;
    if (GleapFeedbackButtonManager.getInstance().buttonHidden === null) {
      if (flowConfig.feedbackButtonPosition === GleapFeedbackButtonManager.FEEDBACK_BUTTON_NONE) {
        hideButton = true;
      }
    } else {
      if (GleapFeedbackButtonManager.getInstance().buttonHidden) {
        hideButton = true;
      }
    }
    if (hideButton) {
      this.feedbackButton.classList.add('bb-feedback-button--disabled');
    }

    if (flowConfig.feedbackButtonPosition === GleapFeedbackButtonManager.FEEDBACK_BUTTON_BOTTOM_LEFT) {
      this.feedbackButton.classList.add('bb-feedback-button--bottomleft');
    }

    const appMode = GleapFrameManager.getInstance().appMode;

    // An inline survey page doesn't open the messenger: the launcher keeps its state.
    if (GleapFrameManager.getInstance().isOpened() && appMode !== 'survey_page') {
      this.feedbackButton.classList.add('bb-feedback-button--open');
    }

    if (appMode === 'survey' || appMode === 'survey_full' || appMode === 'survey_web') {
      this.feedbackButton.classList.add('bb-feedback-button--survey');
    }

    if (flowConfig.hideForGuests === true && !GleapSession.getInstance().isUser()) {
      this.feedbackButton.classList.add('bb-feedback-button--hidden');
    }
  }
}
